from pathlib import Path
import wave, math, struct, random
root=Path(__file__).resolve().parent.parent/'public'
noise='<filter id="grain"><feTurbulence type="fractalNoise" baseFrequency=".7" numOctaves="3" stitchTiles="stitch"/><feColorMatrix type="saturate" values="0"/><feComponentTransfer><feFuncA type="linear" slope=".12"/></feComponentTransfer></filter>'
def save(name,body):
 (root/'art'/f'{name}.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" width="600" height="600" viewBox="0 0 600 600"><defs>{noise}</defs>{body}<rect width="600" height="600" filter="url(#grain)" opacity=".6"/></svg>')
def label(top,bottom,color='#fff'):
 return f'<g fill="{color}" font-family="Arial,sans-serif"><text x="35" y="49" font-size="11" letter-spacing="4">TSPOT / ORIGINALS</text><text x="35" y="490" font-size="58" font-weight="700" letter-spacing="-3">{top}</text><text x="35" y="550" font-size="58" font-weight="700" letter-spacing="-3">{bottom}</text><text x="550" y="50" font-size="12" text-anchor="end">↗</text></g>'
save('night','''<defs><linearGradient id="bg" x2="1" y2="1"><stop stop-color="#171e36"/><stop offset="1" stop-color="#647068"/></linearGradient><radialGradient id="glow"><stop stop-color="#f7bd87"/><stop offset=".65" stop-color="#d88e6b"/><stop offset="1" stop-color="#634e62"/></radialGradient></defs><rect width="600" height="600" fill="url(#bg)"/><circle cx="382" cy="220" r="143" fill="url(#glow)"/><path d="M0 370L90 300 165 350 267 285 430 370 530 305 600 340V600H0Z" fill="#1f2e33"/><path d="M0 415L95 361 210 430 380 345 600 415V600H0Z" fill="#15242b"/><path d="M350 370Q300 400 325 430T275 600" fill="none" stroke="#b0967a" stroke-width="7" opacity=".5"/>'''+label('AFTER','HOURS.','#e8ddcb'))
save('bloom','''<defs><linearGradient id="bg" x2="0" y2="1"><stop stop-color="#b7b6bd"/><stop offset="1" stop-color="#717e6a"/></linearGradient><radialGradient id="petal"><stop stop-color="#fcdee7"/><stop offset=".6" stop-color="#d88fba"/><stop offset="1" stop-color="#845e84"/></radialGradient></defs><rect width="600" height="600" fill="url(#bg)"/><g transform="translate(310 270)">'''+''.join(f'<ellipse cx="0" cy="-78" rx="66" ry="122" fill="url(#petal)" transform="rotate({i*51.4})"/>' for i in range(7))+'''<circle r="41" fill="#f0cf88"/><circle r="24" fill="#bf9162"/></g>'''+label('SOFT','FOCUS.','#f0e9e7'))
save('sun','''<defs><linearGradient id="bg" x2="0" y2="1"><stop stop-color="#cf7552"/><stop offset="1" stop-color="#f0c486"/></linearGradient></defs><rect width="600" height="600" fill="url(#bg)"/><circle cx="306" cy="260" r="153" fill="#f9dda2"/><g fill="none" stroke="#cf7953" stroke-width="3">'''+''.join(f'<ellipse cx="300" cy="{370+i*15}" rx="{220+i*13}" ry="{15+i*3}"/>' for i in range(12))+'''</g>'''+label('GOLDEN','HOUR.','#703e2d'))
save('ocean','''<defs><linearGradient id="bg" x2="0" y2="1"><stop stop-color="#a4bcb1"/><stop offset=".55" stop-color="#557e81"/><stop offset="1" stop-color="#152e48"/></linearGradient></defs><rect width="600" height="600" fill="url(#bg)"/><circle cx="430" cy="125" r="42" fill="#e8e2bc" opacity=".7"/><path d="M0 330Q120 170 280 315T600 240V600H0Z" fill="#326b70"/><path d="M0 350Q120 200 280 340T600 265" fill="none" stroke="#bfd1be" stroke-width="5" opacity=".7"/><path d="M0 450Q190 280 350 405T600 365V600H0Z" fill="#244c5b"/>'''+label('OCEAN','DRIVE.','#eceddd'))
save('blue','''<defs><linearGradient id="bg" x2="1" y2="1"><stop stop-color="#182e64"/><stop offset="1" stop-color="#8aa3cd"/></linearGradient><linearGradient id="orb" x2="1" y2="1"><stop stop-color="#c4d0ea"/><stop offset=".45" stop-color="#6082bb"/><stop offset="1" stop-color="#16254f"/></linearGradient></defs><rect width="600" height="600" fill="url(#bg)"/><g transform="translate(310 260) rotate(-30)"><ellipse rx="175" ry="90" fill="none" stroke="#b0c3e2" stroke-width="21"/><ellipse rx="115" ry="165" fill="none" stroke="url(#orb)" stroke-width="50"/><circle r="80" fill="url(#orb)"/></g>'''+label('BLUE','NOTES.','#e5edf9'))
save('desert','''<defs><linearGradient id="bg" x2="0" y2="1"><stop stop-color="#e4ceaa"/><stop offset="1" stop-color="#b78e63"/></linearGradient></defs><rect width="600" height="600" fill="url(#bg)"/><circle cx="200" cy="170" r="67" fill="#f3e5bd"/><path d="M0 330Q170 210 370 330T600 340V600H0Z" fill="#bc966c"/><path d="M0 410Q250 230 600 390V600H0Z" fill="#98744f"/><path d="M370 600Q150 480 390 350" fill="none" stroke="#d6b78b" stroke-width="4"/>'''+label('EASY','DAYS.','#f7e9d2'))
(root/'art'/'hero.svg').write_text('''<svg xmlns="http://www.w3.org/2000/svg" width="1400" height="600" viewBox="0 0 1400 600"><defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="#142e26"/><stop offset=".65" stop-color="#537459"/><stop offset="1" stop-color="#879778"/></linearGradient><radialGradient id="moon"><stop stop-color="#e2e8b9"/><stop offset=".6" stop-color="#c6d49a"/><stop offset="1" stop-color="#92ae71"/></radialGradient><linearGradient id="road" x2="0" y2="1"><stop stop-color="#8fa274"/><stop offset="1" stop-color="#192e26"/></linearGradient>'''+noise+'''</defs><rect width="1400" height="600" fill="url(#sky)"/><circle cx="1000" cy="228" r="176" fill="url(#moon)"/><circle cx="1000" cy="228" r="203" fill="none" stroke="#e4eaca" opacity=".09"/><path d="M0 355L110 302 210 340 370 254 480 347 580 300 690 342 810 270 890 328 1080 291 1200 351 1310 266 1400 315V600H0Z" fill="#304e3d"/><path d="M0 392L160 353 240 410 430 345 560 380 710 340 850 390 1010 330 1210 405 1400 350V600H0Z" fill="#203e30"/><path d="M0 470L140 409 330 473 500 395 630 440 780 380 930 440 1110 391 1300 450 1400 408V600H0Z" fill="#152f25"/><path d="M905 380Q1100 430 960 480T730 620" stroke="url(#road)" fill="none" stroke-width="26"/><path d="M905 380Q1100 430 960 480T730 620" stroke="#b0c391" fill="none" stroke-width="1.5" stroke-dasharray="10 14" opacity=".7"/><g fill="#a4be8a" opacity=".4"><circle cx="733" cy="71" r="1"/><circle cx="1260" cy="168" r="1"/><circle cx="858" cy="119" r="1.5"/><circle cx="1120" cy="51" r="1"/></g><rect width="1400" height="600" filter="url(#grain)" opacity=".8"/></svg>''')
# Original synthesized ambient loops: chord pads, a soft bass and a light beat.
sr=16000
chords=[(130.81,164.81,196),(146.83,174.61,220),(164.81,196,246.94),(110,130.81,164.81)]
for idx,duration in enumerate([48,44,52,40,48,44,48,44]):
 random.seed(idx);out=bytearray();shift=[1,.89,1.12,.75,1.33,.84,1.06,.94][idx]
 for n in range(sr*duration):
  t=n/sr;local=t%4; chord=chords[(int(t/4)+idx)%4];env=min(local/.4,1,(4-local)/.6);value=0
  for f in chord:
   value+=.065*math.sin(math.tau*f*shift*t)+.022*math.sin(math.tau*f*2*shift*t+.4)
  value*=max(0,env)*(.85+.15*math.sin(t*.7));value+=.055*math.sin(math.tau*chord[0]/2*shift*t)
  beat=t%(.5 if idx%2==0 else .6);value+=.11*math.exp(-beat*24)*math.sin(math.tau*(45*beat+2*(1-math.exp(-beat*20))))
  hat=(t+.25)% .5;value+=(random.random()-.5)*.025*math.exp(-hat*70)
  value*=min(1,t/1.5,(duration-t)/2)
  out.extend(struct.pack('<h',int(max(-1,min(1,value))*32767)))
 with wave.open(str(root/'audio'/f'{idx}.wav'),'wb') as w:w.setnchannels(1);w.setsampwidth(2);w.setframerate(sr);w.writeframes(out)
